import type { VoterDatabaseImportStatus } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge/index';

interface VoterDatabaseStatusEntry {
  color: string;
  variant: BadgeVariants;
}

export const voterDatabaseStatusConfig: Record<VoterDatabaseImportStatus, VoterDatabaseStatusEntry> = {
  pending: { color: 'bg-blue-200 text-blue-800', variant: 'default' },
  processing: { color: 'bg-blue-200 text-blue-800', variant: 'default' },
  indexing: { color: 'bg-blue-200 text-blue-800', variant: 'default' },
  geocoding: { color: 'bg-blue-200 text-blue-800', variant: 'default' },
  imported: { color: 'bg-green-200 text-green-800', variant: 'success' },
  failed: { color: 'bg-red-200 text-red-800', variant: 'destructive' },
  removed: { color: 'bg-gray-200 text-gray-800', variant: 'default' },
};

const defaultVoterDatabaseStatus: VoterDatabaseStatusEntry = { color: 'bg-gray-200 text-gray-800', variant: 'default' };

export function getVoterDatabaseStatus(status: VoterDatabaseImportStatus): VoterDatabaseStatusEntry {
  return voterDatabaseStatusConfig[status] ?? defaultVoterDatabaseStatus;
}
